package iq.yasserapps.studio;
import java.io.*;import java.util.*;import java.util.zip.*;import java.nio.charset.StandardCharsets;import java.util.regex.*;import java.util.function.BooleanSupplier;
public final class WindowInventory {
 static final Pattern HINT=Pattern.compile("update available|check.?update|optional.?update|telegram|t\\.me/|subscribe|don't show again|تحديث|اشتراك|تيليجرام",Pattern.CASE_INSENSITIVE);
 static final long TOTAL=2L*1024*1024*1024, PER=256L*1024*1024, TIME=300000000000L;static final int CHUNK=32768,OVERLAP=512;
 public interface Progress {void tick(int done,int total,String name);}
 public static final class Result{public int scanned,skipped,matched,errors,total;public long bytes,scanMillis;public boolean partial;public String reason="";final Map<String,Integer> counts=new LinkedHashMap<>();final List<String> hits=new ArrayList<>();public String report(){return "فحص مصادر متعدد — بحث عن وجود مؤشر، يتوقف داخل الملف عند أول تطابق\n"+counts+"\nعدد الملفات المفحوصة: "+scanned+" / "+total+"\nالملفات المتجاوزة: "+skipped+"\nأخطاء القراءة: "+errors+"\nمدة الفحص (مللي ثانية): "+scanMillis+"\nبايتات مقروءة: "+bytes+"\nملفات تحمل مؤشرات: "+matched+"\n"+(partial?"نتيجة جزئية: "+reason+"\n":"")+"\n"+String.join("\n",hits)+"\nوجود المؤشر لا يثبت وظيفة النافذة، ولا يعني إمكان تعديلها تلقائياً.";}}
 static String kind(String n){String low=n.toLowerCase(Locale.ROOT);return ApkEngine.DEX_NAME.matcher(low).matches()?"DEX":low.endsWith(".smali")?"Smali":low.equals("resources.arsc")?"ARSC":low.endsWith(".xml")?"XML":low.startsWith("lib/")&&low.endsWith(".so")?"Native":low.startsWith("assets/")||low.endsWith(".json")?"Assets/JSON":null;}
 static boolean matches(byte[] b,int len,boolean wide){if(HINT.matcher(new String(b,0,len,StandardCharsets.UTF_8)).find())return true;if(wide){for(int off=0;off<=1;off++){int n=(len-off)&~1;if(n>0&&HINT.matcher(new String(b,off,n,StandardCharsets.UTF_16LE)).find())return true;}}return false;}
 static boolean stop(Result r,BooleanSupplier cancel,long deadline){if(cancel.getAsBoolean()){r.partial=true;r.reason="أُلغي الفحص";return true;}if(System.nanoTime()-deadline>=0){r.partial=true;r.reason="انتهت مهلة الفحص";return true;}if(r.bytes>=TOTAL){r.partial=true;r.reason="بلغ حد القراءة";return true;}return false;}
 public static Result scan(File f,Progress progress,BooleanSupplier cancel)throws IOException{Result r=new Result();long start=System.nanoTime(),deadline=start+TIME;long last=0;Set<String> seen=new HashSet<>();try(ZipFile z=new ZipFile(f)){List<ZipEntry> entries=new ArrayList<>();Enumeration<? extends ZipEntry> es=z.entries();while(es.hasMoreElements()){ZipEntry e=es.nextElement();ApkEngine.valid(e,seen);if(seen.size()>50000)throw new IOException("Too many ZIP entries");if(!e.isDirectory()&&kind(e.getName())!=null)entries.add(e);}entries.sort(Comparator.comparingInt(e->{String k=kind(e.getName());return "DEX".equals(k)?0:"ARSC".equals(k)?1:"XML".equals(k)?2:"Native".equals(k)?4:3;}));r.total=entries.size();int done=0;byte[] b=new byte[CHUNK+OVERLAP];for(ZipEntry e:entries){if(stop(r,cancel,deadline))break;String n=e.getName(),k=kind(n);r.counts.put(k,r.counts.getOrDefault(k,0)+1);long now=System.nanoTime();if(done==0||now-last>200000000L){progress.tick(done,r.total,n);last=now;}long fileLimit="DEX".equals(k)?512L*1024*1024:PER;boolean found=false,complete=false;long fileBytes=0;int carry=0;try(InputStream in=z.getInputStream(e)){while(true){if(stop(r,cancel,deadline))break;int want=(int)Math.min(CHUNK,Math.min(TOTAL-r.bytes,fileLimit-fileBytes));if(want<=0){complete=fileBytes==e.getSize();break;}int read=in.read(b,carry,want);if(read<0){complete=true;break;}if(read==0)throw new IOException("Zero-byte read");fileBytes+=read;r.bytes+=read;int len=carry+read;if(matches(b,len,"XML".equals(k)||"ARSC".equals(k))){found=true;complete=true;break;}carry=Math.min(OVERLAP,len);System.arraycopy(b,len-carry,b,0,carry);if(fileBytes==e.getSize()){complete=true;break;}}}catch(IOException ex){r.errors++;}if(found){r.matched++;if(r.hits.size()<100)r.hits.add(k+": "+n);}if(complete)r.scanned++;else r.skipped++;done++;if(r.partial)break;}if(done<r.total){r.partial=true;if(r.reason.isEmpty())r.reason="فحص غير مكتمل";r.skipped+=r.total-done;}else if(r.skipped>0||r.errors>0){r.partial=true;if(r.reason.isEmpty())r.reason="بعض الملفات تجاوزت الحدود أو تعذرت قراءتها";}r.scanMillis=(System.nanoTime()-start)/1000000L;progress.tick(done,r.total,r.partial?"فحص جزئي":"اكتمل");}return r;}
 public static String inspect(File f)throws IOException{return scan(f,(a,b,c)->{},()->false).report();}
}